namespace Aurora {
public sealed class DriverMachineContext {
    public string Manufacturer="",Model="",Sku="",Board="",Release="",Arch=Environment.Is64BitOperatingSystem?"x64":"x86";public int Build;
    public static DriverMachineContext Read(){var value=new DriverMachineContext{Build=Environment.OSVersion.Version.Build};try{foreach(var item in Machine.Query("root\\cimv2","SELECT Manufacturer,Model,SystemSKUNumber FROM Win32_ComputerSystem"))using(item){value.Manufacturer=Machine.Value(item,"Manufacturer");value.Model=Machine.Value(item,"Model");value.Sku=Machine.Value(item,"SystemSKUNumber");}}catch{}value.Board=Machine.First("SELECT Product FROM Win32_BaseBoard","Product");try{using(var key=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion")){value.Release=Convert.ToString(key.GetValue("DisplayVersion",key.GetValue("ReleaseId","")));int build;if(Int32.TryParse(Convert.ToString(key.GetValue("CurrentBuildNumber")),out build))value.Build=build;}}catch{}return value;}
}
public sealed class CatalogDriver {
    public string Source,Id,Title,Version,Date,Products,Url,Hash,HashAlgorithm,Reason;public DriverRecord Device;
    public string Details{get{return Title+"\n"+Source+" • "+Version+" • "+Date+"\n"+L.T("Instalada: ","Installed: ")+(Device==null?"—":Device.Version)+"\n"+Products+"\n"+Reason;}}
    public override string ToString(){return Source+" • "+Title+"\n"+L.T("Atual: ","Current: ")+(Device==null?"—":Device.Version)+" → "+Version;}
}
public static class DriverCatalogs {
    public static string Cache{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OuO","DriverCatalogs");}}
    static bool Host(string host,string suffix){return host.Equals(suffix,StringComparison.OrdinalIgnoreCase)||host.EndsWith("."+suffix,StringComparison.OrdinalIgnoreCase);}
    public static bool AllowedUrl(string address){Uri url;return Uri.TryCreate(address,UriKind.Absolute,out url)&&url.Scheme=="https"&&url.UserInfo==""&&(Host(url.Host,"catalog.update.microsoft.com")||Host(url.Host,"windowsupdate.com")||Host(url.Host,"download.microsoft.com")||url.Host.Equals("downloads.dell.com",StringComparison.OrdinalIgnoreCase)||url.Host.Equals("dl.dell.com",StringComparison.OrdinalIgnoreCase)||url.Host.Equals("ftp.hp.com",StringComparison.OrdinalIgnoreCase));}
    static HttpWebResponse Request(string address,string form=null,int redirects=0){if(redirects>5)throw new InvalidDataException("Too many catalog redirects");if(!AllowedUrl(address))throw new InvalidDataException("Driver URL is outside official source hosts");ServicePointManager.SecurityProtocol|=(SecurityProtocolType)3072;var request=(HttpWebRequest)WebRequest.Create(address);request.UserAgent="OuO Driver Catalog/1.0";request.Timeout=45000;request.ReadWriteTimeout=45000;request.AllowAutoRedirect=false;if(form!=null){request.Method="POST";request.ContentType="application/x-www-form-urlencoded";byte[] body=Encoding.UTF8.GetBytes(form);request.ContentLength=body.Length;using(var stream=request.GetRequestStream())stream.Write(body,0,body.Length);}var response=(HttpWebResponse)request.GetResponse();if((int)response.StatusCode>=300&&(int)response.StatusCode<400){string next=response.Headers["Location"];response.Dispose();if(!Uri.IsWellFormedUriString(next,UriKind.Absolute))next=new Uri(new Uri(address),next).AbsoluteUri;if(!AllowedUrl(next))throw new InvalidDataException("Driver redirect left official hosts");return Request(next,form,redirects+1);}return response;}
    public static string Text(string address,string form=null){using(var response=Request(address,form))using(var stream=response.GetResponseStream())using(var reader=new StreamReader(stream,Encoding.UTF8)){char[] buffer=new char[8192];var text=new StringBuilder();int count;while((count=reader.Read(buffer,0,buffer.Length))>0){if(text.Length+count>8000000)throw new InvalidDataException("Catalog response is too large");text.Append(buffer,0,count);}return text.ToString();}}
    public static void Download(string address,string file,long limit,Action<long,long> progress=null){if(!AllowedUrl(address))throw new InvalidDataException("Untrusted download source");using(var response=Request(address))using(var input=response.GetResponseStream())using(var output=new FileStream(file,FileMode.CreateNew,FileAccess.Write,FileShare.None)){if(response.ContentLength>limit)throw new IOException("Driver package exceeds download limit");byte[] bytes=new byte[65536];long total=0;int count;while((count=input.Read(bytes,0,bytes.Length))>0){total+=count;if(total>limit)throw new IOException("Driver package exceeds download limit");output.Write(bytes,0,count);if(progress!=null)progress(total,response.ContentLength);}}}
    static string Plain(string html){return Regex.Replace(WebUtility.HtmlDecode(Regex.Replace(html??"",@"<[^>]+>"," ")),@"\s+"," ").Trim();}
    public static Version Numeric(string text){Match m=Regex.Match(text??"",@"\d+(?:\.\d+){1,3}");Version value;return m.Success&&Version.TryParse(m.Value,out value)?value:null;}
    public static bool Newer(CatalogDriver candidate){Version have=Numeric(candidate.Device==null?"":candidate.Device.Version),next=Numeric(candidate.Version);return have!=null&&next!=null&&next>have;}
    static bool Os(string products,DriverMachineContext machine){string text=(products??"").ToLowerInvariant();return machine.Build>=22000?text.Contains("windows 11"):machine.Build>=10240?text.Contains("windows 10"):machine.Build>=9600?text.Contains("windows 8.1"):machine.Build>=9200?text.Contains("windows 8"):text.Contains("windows 7");}
    public static List<CatalogDriver> MicrosoftParse(string html,DriverRecord device,DriverMachineContext context){var result=new List<CatalogDriver>();foreach(Match row in Regex.Matches(html??"",@"<tr\b[^>]*\bid=[\""'](?<id>[0-9a-f-]{36})_R\d+[\""'][^>]*>(?<body>.*?)</tr>",RegexOptions.IgnoreCase|RegexOptions.Singleline)){
        var cells=Regex.Matches(row.Groups["body"].Value,@"<td\b[^>]*>(.*?)</td>",RegexOptions.IgnoreCase|RegexOptions.Singleline).Cast<Match>().Select(x=>Plain(x.Groups[1].Value)).ToArray();if(cells.Length<7||!cells[3].StartsWith("Drivers",StringComparison.OrdinalIgnoreCase)||!Os(cells[2],context))continue;
        Guid id;if(!Guid.TryParse(row.Groups["id"].Value,out id))continue;result.Add(new CatalogDriver{Source="Microsoft Catalog",Id=id.ToString(),Title=cells[1],Products=cells[2],Date=cells[4],Version=cells[5],Device=device,Reason=L.T("Resultado pelo ID de hardware; arquitetura e INF serão conferidos antes da instalação.","Hardware-ID search result; architecture and INF are checked before installation.")});
    }return result;}
    public static List<CatalogDriver> Microsoft(DriverRecord device,DriverMachineContext context){string hardware=(device.HardwareIds??new string[0]).FirstOrDefault(x=>Regex.IsMatch(x,@"^(PCI|USB|HDAUDIO)\\",RegexOptions.IgnoreCase))??device.DeviceId;if(String.IsNullOrWhiteSpace(hardware))return new List<CatalogDriver>();var result=MicrosoftParse(Text("https://www.catalog.update.microsoft.com/Search.aspx?q="+Uri.EscapeDataString(hardware)),device,context);if(result.Count==0){string basic=Regex.Match(hardware,@"^(?:PCI\\VEN_[0-9A-F]{4}&DEV_[0-9A-F]{4}|USB\\VID_[0-9A-F]{4}&PID_[0-9A-F]{4})",RegexOptions.IgnoreCase).Value;if(basic!=""&&basic!=hardware)result=MicrosoftParse(Text("https://www.catalog.update.microsoft.com/Search.aspx?q="+Uri.EscapeDataString(basic)),device,context);}return result;}
    public static List<Tuple<string,string>> MicrosoftFiles(string html){var result=new List<Tuple<string,string>>();foreach(Match file in Regex.Matches(html??"",@"files\[(?<index>\d+)\]\.url\s*=\s*'(?<url>[^']+)'",RegexOptions.IgnoreCase)){
        string url=WebUtility.HtmlDecode(file.Groups["url"].Value.Replace("\\/","/"));if(!AllowedUrl(url)||!new Uri(url).AbsolutePath.EndsWith(".cab",StringComparison.OrdinalIgnoreCase))continue;Match hash=Regex.Match(html,@"files\["+file.Groups["index"].Value+@"\]\.sha256\s*=\s*'([^']+)'",RegexOptions.IgnoreCase);result.Add(Tuple.Create(url,hash.Success?hash.Groups[1].Value:""));
    }return result;}
    public static string ExpandCatalog(string cab,string xmlName,string destination){Directory.CreateDirectory(destination);var result=Runner.Run("expand.exe","-F:"+xmlName+" "+Args.Q(cab)+" "+Args.Q(destination),120000);string expected=Path.Combine(destination,xmlName);if(File.Exists(expected))return expected;string alternate=Path.Combine(destination,Path.GetFileName(cab));if(File.Exists(alternate)){using(var input=File.OpenRead(alternate)){byte[] magic=new byte[4];input.Read(magic,0,4);if(Encoding.ASCII.GetString(magic)!="MSCF"){File.Move(alternate,expected);return expected;}}}throw new IOException("Catalog extraction failed: "+result.Output);}
    static string Catalog(string provider){Directory.CreateDirectory(Cache);string cached=Path.Combine(Cache,provider+".xml");if(File.Exists(cached)&&DateTime.UtcNow-File.GetLastWriteTimeUtc(cached)<TimeSpan.FromHours(24))return cached;string work=Path.Combine(Cache,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);string cab=Path.Combine(work,"catalog.cab"),url=provider=="Dell"?"https://downloads.dell.com/catalog/CatalogPC.cab":"https://ftp.hp.com/pub/softlib/software/sms_catalog/HpCatalogForSms.latest.cab";Download(url,cab,30000000);string xml=ExpandCatalog(cab,provider=="Dell"?"CatalogPC.xml":"HpCatalogForSms.xml",Path.Combine(work,"expanded"));File.Copy(xml,cached,true);return cached;}
    static IEnumerable<XElement> Items(string file,string name){using(var reader=XmlReader.Create(file,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=300000000}))while(reader.Read())if(reader.NodeType==XmlNodeType.Element&&reader.LocalName==name){using(var sub=reader.ReadSubtree())yield return XElement.Load(sub);}}
    static IEnumerable<XElement> Nodes(XElement element,string name){return element.Descendants().Where(x=>x.Name.LocalName==name);}
    static string Value(XElement element,string name){return Nodes(element,name).Select(x=>x.Value).FirstOrDefault()??"";}
    static bool Hardware(DriverRecord device,string id){string token=(id??"").Replace("\\\\","\\").Trim('%');return token.Length>=8&&device.HardwareIds.Concat(new[]{device.DeviceId}).Any(x=>!String.IsNullOrEmpty(x)&&x.IndexOf(token,StringComparison.OrdinalIgnoreCase)>=0);}
    public static List<CatalogDriver> DellParse(string file,DriverRecord device,DriverMachineContext context){var result=new List<CatalogDriver>();if(context.Manufacturer.IndexOf("Dell",StringComparison.OrdinalIgnoreCase)<0)return result;foreach(var component in Items(file,"SoftwareComponent")){
        if(!Nodes(component,"ComponentType").Any(x=>(string)x.Attribute("value")=="DRVR"))continue;
        bool model=Nodes(component,"Model").Any(x=>!String.IsNullOrWhiteSpace(context.Sku)&&String.Equals((string)x.Attribute("systemID"),context.Sku,StringComparison.OrdinalIgnoreCase)||!String.IsNullOrWhiteSpace(context.Model)&&Plain(x.Value).Replace("-"," ").Equals(context.Model.Replace("-"," "),StringComparison.OrdinalIgnoreCase));if(!model)continue;
        bool hardware=Nodes(component,"PCIInfo").Any(x=>Hardware(device,@"PCI\VEN_"+(string)x.Attribute("vendorID")+"&DEV_"+(string)x.Attribute("deviceID")));if(!hardware)continue;
        string systems=String.Join("; ",Nodes(component,"OperatingSystem").Where(x=>String.Equals((string)x.Attribute("osArch"),context.Arch,StringComparison.OrdinalIgnoreCase)).Select(x=>x.Value));if(!Os(systems,context))continue;
        string path=(string)component.Attribute("path");if(String.IsNullOrWhiteSpace(path)||path.Contains("..")||path.StartsWith("/"))continue;string url="https://downloads.dell.com/"+path;
        result.Add(new CatalogDriver{Source="Dell",Id=(string)component.Attribute("releaseID"),Title=Value(component,"Name").Trim(),Version=(string)component.Attribute("vendorVersion"),Date=(string)component.Attribute("releaseDate"),Url=url,Products=systems,Device=device,Reason=L.T("Modelo, sistema e hardware encontrados no catálogo oficial Dell.","Model, OS and hardware found in Dell's official catalog.")});
    }return result;}
    public static bool HpRule(XElement rule,DriverRecord device,DriverMachineContext context){return HpEvaluation(rule,device,context)==true;}
    static bool? HpEvaluation(XElement rule,DriverRecord device,DriverMachineContext context){if(rule==null)return null;string name=rule.Name.LocalName;var children=rule.Elements().ToArray();if(name=="IsInstallable"||name=="ApplicabilityRules")return children.Length==1?HpEvaluation(children[0],device,context):null;if(name=="And"||name=="Or"){var values=children.Select(x=>HpEvaluation(x,device,context)).ToArray();if(name=="And")return values.Contains(false)?false:values.Contains(null)?(bool?)null:values.Length>0;if(values.Contains(true))return true;return values.Contains(null)?(bool?)null:false;}if(name=="Not")return children.Length==1?!HpEvaluation(children[0],device,context):null;if(name=="True")return true;if(name=="False")return false;
        if(name=="Processor")return (string)rule.Attribute("Architecture")== (context.Arch=="x64"?"9":context.Arch=="arm64"?"12":"0");
        if(name=="WindowsVersion"){int major=0,minor=0;Int32.TryParse((string)rule.Attribute("MajorVersion"),out major);Int32.TryParse((string)rule.Attribute("MinorVersion"),out minor);int currentMajor=context.Build>=10240?10:6,currentMinor=context.Build>=9600?3:context.Build>=9200?2:1;Version have=new Version(currentMajor,currentMajor==10?0:currentMinor),wanted=new Version(major,minor);string comparison=(string)rule.Attribute("Comparison");return comparison=="EqualTo"?have==wanted:comparison=="GreaterThanOrEqualTo"?have>=wanted:comparison=="GreaterThan"?have>wanted:false;}
        if(name=="RegSz"){if((string)rule.Attribute("Key")!="HKEY_LOCAL_MACHINE"||(string)rule.Attribute("Comparison")!="EqualTo")return null;string key=(string)rule.Attribute("Subkey"),value=(string)rule.Attribute("Value"),data=(string)rule.Attribute("Data");if(!String.Equals(key,@"Software\Microsoft\Windows NT\CurrentVersion",StringComparison.OrdinalIgnoreCase)||(value!="DisplayVersion"&&value!="ReleaseId"))return null;return String.Equals(context.Release,data,StringComparison.OrdinalIgnoreCase);}
        if(name=="WmiQuery"){string query=(string)rule.Attribute("WqlQuery")??"";if(query.IndexOf("Win32_ComputerSystem",StringComparison.OrdinalIgnoreCase)>=0){string normalized=Regex.Replace(query,@"\s+","").ToLowerInvariant();if(normalized!="select*fromwin32_computersystemwhere(manufacturer='hewlett-packard'andnot(modellike'%proliant%'))or(manufacturer='hp')")return null;return context.Manufacturer.Equals("HP",StringComparison.OrdinalIgnoreCase)||context.Manufacturer.Equals("Hewlett-Packard",StringComparison.OrdinalIgnoreCase)&&context.Model.IndexOf("Proliant",StringComparison.OrdinalIgnoreCase)<0;}
            if(query.IndexOf("Win32_BaseBoard",StringComparison.OrdinalIgnoreCase)>=0){var codes=Regex.Matches(query,@"Product\s+(?:LIKE|=)\s*'([^']+)'",RegexOptions.IgnoreCase).Cast<Match>().Select(x=>x.Groups[1].Value.Trim('%')).ToArray();return codes.Length>0&&codes.Any(x=>context.Board.IndexOf(x,StringComparison.OrdinalIgnoreCase)>=0);}
            if(query.IndexOf("Win32_PnpEntity",StringComparison.OrdinalIgnoreCase)>=0)return Regex.Matches(query,@"DeviceID\s+(?:LIKE|=)\s*'([^']+)'",RegexOptions.IgnoreCase).Cast<Match>().Any(x=>Hardware(device,x.Groups[1].Value));
        }return null;
    }
    public static List<CatalogDriver> HpParse(string file,DriverRecord device,DriverMachineContext context){var result=new List<CatalogDriver>();if(context.Manufacturer.IndexOf("HP",StringComparison.OrdinalIgnoreCase)<0&&context.Manufacturer.IndexOf("Hewlett",StringComparison.OrdinalIgnoreCase)<0)return result;foreach(var package in Items(file,"SoftwareDistributionPackage")){
        string title=Value(package,"Title");if(title.IndexOf("driver",StringComparison.OrdinalIgnoreCase)<0)continue;var general=package.Elements().FirstOrDefault(x=>x.Name.LocalName=="IsInstallable");if(!HpRule(general,device,context))continue;
        foreach(var item in Nodes(package,"InstallableItem")){var install=Nodes(item,"IsInstallable").FirstOrDefault();if(!HpRule(install,device,context)||!Nodes(item,"WmiQuery").Any(q=>((string)q.Attribute("WqlQuery")??"").IndexOf("Win32_PnpEntity",StringComparison.OrdinalIgnoreCase)>=0&&HpRule(q,device,context)))continue;var origin=Nodes(item,"OriginFile").FirstOrDefault();if(origin==null)continue;string url=(string)origin.Attribute("OriginUri");if(!AllowedUrl(url))continue;string version=Regex.Match(title,@"\[([^\]]+)\]").Groups[1].Value;
            result.Add(new CatalogDriver{Source="HP",Id=Value(package,"KBArticleID"),Title=title,Version=version,Date=(string)origin.Attribute("Modified"),Url=url,Hash=(string)origin.Attribute("Digest"),HashAlgorithm="SHA1",Products="Windows "+context.Release+" • "+context.Arch,Device=device,Reason=L.T("Regras de modelo, sistema e dispositivo do catálogo HP atendidas.","HP catalog model, OS and device rules matched.")});break;
        }
    }return result;}
    public static List<CatalogDriver> Search(DriverRecord device,bool microsoft,bool oem,bool otherVersions,Action<string> stage,List<string> notes){if(device==null)throw new ArgumentException("Select a device");var machine=DriverMachineContext.Read();var found=new List<CatalogDriver>();if(microsoft)try{if(stage!=null)stage("Microsoft Catalog");found.AddRange(Microsoft(device,machine));}catch(Exception ex){notes.Add("Microsoft Catalog • "+ex.Message);}if(oem){if(machine.Manufacturer.IndexOf("Dell",StringComparison.OrdinalIgnoreCase)>=0)try{if(stage!=null)stage("Dell Catalog");found.AddRange(DellParse(Catalog("Dell"),device,machine));}catch(Exception ex){notes.Add("Dell • "+ex.Message);}else if(machine.Manufacturer.IndexOf("HP",StringComparison.OrdinalIgnoreCase)>=0||machine.Manufacturer.IndexOf("Hewlett",StringComparison.OrdinalIgnoreCase)>=0)try{if(stage!=null)stage("HP Catalog");found.AddRange(HpParse(Catalog("HP"),device,machine));}catch(Exception ex){notes.Add("HP • "+ex.Message);}else notes.Add(L.T("Este fabricante não usa os catálogos Dell/HP; o Catálogo Microsoft permanece disponível.","This manufacturer does not use Dell/HP catalogs; Microsoft Catalog remains available."));}
        return found.Where(x=>otherVersions||Newer(x)).GroupBy(x=>x.Source+"|"+x.Id).Select(x=>x.First()).OrderByDescending(x=>Numeric(x.Version)).Take(100).ToList();
    }
    public static void CheckDigest(string file,string expected,string algorithm){if(String.IsNullOrWhiteSpace(expected))return;byte[] wanted;if(Regex.IsMatch(expected,"^(?:[0-9a-f]{40}|[0-9a-f]{64})$",RegexOptions.IgnoreCase))wanted=Enumerable.Range(0,expected.Length/2).Select(i=>Convert.ToByte(expected.Substring(i*2,2),16)).ToArray();else wanted=Convert.FromBase64String(expected);using(HashAlgorithm hash=algorithm=="SHA1"?(HashAlgorithm)SHA1.Create():SHA256.Create())using(var input=File.OpenRead(file))if(!hash.ComputeHash(input).SequenceEqual(wanted))throw new InvalidDataException("Driver package checksum mismatch");}
    static void SignedOem(string file,string source){string publisher=source=="Dell"?"Dell Inc|Dell Technologies":"Hewlett-Packard|HP Inc";var check=Runner.PS("$s=Get-AuthenticodeSignature -LiteralPath "+Runner.QuotePS(file)+";if($s.Status -ne 'Valid' -or $null -eq $s.SignerCertificate -or $s.SignerCertificate.Subject -notmatch "+Runner.QuotePS(publisher)+"){throw 'Publisher signature does not match the selected manufacturer'};Write-Output $s.SignerCertificate.Subject",30000);if(check.Code!=0)throw new InvalidDataException(check.Output);var metadata=FileVersionInfo.GetVersionInfo(file);if(Regex.IsMatch((metadata.FileDescription??"")+" "+(metadata.ProductName??""),"BIOS|Firmware",RegexOptions.IgnoreCase))throw new InvalidDataException("Firmware and BIOS packages are outside driver installation");}
    public static string Install(CatalogDriver candidate,int build,Action<string> stage){if(candidate==null||candidate.Device==null)throw new ArgumentException("Select a catalog driver");var current=DriverInventory.Read(true).FirstOrDefault(x=>String.Equals(x.DeviceId,candidate.Device.DeviceId,StringComparison.OrdinalIgnoreCase));if(current==null)throw new InvalidDataException("Selected device is no longer present");candidate.Device=current;DailyMaintenance.ProtectRoot();string work=Path.Combine(DailyMaintenance.Root,"Driver-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);var packages=new List<Tuple<string,string>>();
        if(candidate.Source=="Microsoft Catalog"){Guid id;if(!Guid.TryParse(candidate.Id,out id))throw new InvalidDataException("Invalid Microsoft catalog identity");string json=new JavaScriptSerializer().Serialize(new[]{new{size=0,updateID=id.ToString(),uidInfo=id.ToString()}});packages=MicrosoftFiles(Text("https://www.catalog.update.microsoft.com/DownloadDialog.aspx","updateIDs="+Uri.EscapeDataString(json)));if(packages.Count==0)throw new InvalidDataException("No supported CAB package in catalog response");}
        else if(candidate.Source=="Dell"||candidate.Source=="HP"){if(!AllowedUrl(candidate.Url))throw new InvalidDataException("Invalid OEM URL");packages.Add(Tuple.Create(candidate.Url,candidate.Hash??""));}else throw new InvalidDataException("Unsupported driver provider");
        int index=0;foreach(var package in packages){string file=Path.Combine(work,"package-"+(++index)+(candidate.Source=="Microsoft Catalog"?".cab":".exe"));if(stage!=null)stage(L.T("Baixando ","Downloading ")+candidate.Title);Download(package.Item1,file,1500000000);CheckDigest(file,package.Item2,candidate.Source=="Microsoft Catalog"?"SHA256":candidate.HashAlgorithm);
            string output=Path.Combine(work,"extracted-"+index);Directory.CreateDirectory(output);if(candidate.Source=="Microsoft Catalog"){
                var listing=Runner.Run("expand.exe","-D "+Args.Q(file),30000);foreach(string line in listing.Output.Split('\n')){int at=line.IndexOf(": ",StringComparison.Ordinal);if(at<0)continue;string name=line.Substring(at+2).Trim();if(name==""||!line.Substring(0,at).EndsWith(".cab",StringComparison.OrdinalIgnoreCase))continue;if(Path.IsPathRooted(name)||name.Contains("..")||name.Contains(":"))throw new InvalidDataException("CAB contains an unsafe member path");}
                var expanded=Runner.Run("expand.exe","-F:* "+Args.Q(file)+" "+Args.Q(output),180000);if(expanded.Code!=0)throw new IOException(expanded.Output);
            }else{SignedOem(file,candidate.Source);string arguments=candidate.Source=="Dell"?"/s /e="+Args.Q(output):"/f"+Args.Q(output)+" /e /s";var extracted=Runner.Run(file,arguments,180000,work);if(extracted.Code!=0&&extracted.Code!=3010)throw new IOException(extracted.Output);}
        }
        var compatible=OfflineDrivers.Scan(work,candidate.Device.HardwareIds.FirstOrDefault()??candidate.Device.DeviceId).Where(x=>OfflineDrivers.ExactMatch(x.Inf,candidate.Device.HardwareIds,candidate.Device.DeviceId)).OrderByDescending(x=>Numeric(x.Version)).ToArray();if(compatible.Length==0)throw new InvalidDataException(L.T("Nenhum INF corresponde exatamente ao dispositivo selecionado; nada foi instalado.","No INF exactly matches the selected device; nothing was installed."));
        var chosen=compatible.First();if(stage!=null)stage(L.T("Instalando ","Installing ")+candidate.Title);return OfflineDrivers.Install(chosen,build)+"\n"+L.T("Pacote e log preservados em ","Package and log preserved at ")+work;
    }
}
}
